// d6800_desk.sv — "Desk" view of the DREAM 6800: the machine, the TV and the cassette recorder
// drawn by art/make_svg.py, 800x600@60 VESA from the 40 MHz clock (positive syncs).
//
// Background: 8x8 tiles of 4-bit pixels (rtl/desk_tiles.hex) placed by a 100x75 map
// (rtl/desk_map.hex); palette, picture origin and key rectangles in rtl/desk_assets.svh
// (all generated by art/build_assets.py).
// Overlays: the 64x32 picture inside the TV (5x5 pixels per dot, phosphor colour from the OSD),
// keys shown pressed, the tape LED, the mouse pointer.
// The picture comes from a 2048-bit copy of what the native video draws (pix sampled on the
// first line of each dot row), so it shows exactly the real screen, DMA off included.

module d6800_desk #(
    parameter TILES_FILE = "rtl/desk_tiles.hex",
    parameter MAP_FILE   = "rtl/desk_map.hex"
) (
    input  logic        clk,            // 40 MHz
    // native video of the machine
    input  logic        ce_dot,
    input  logic        pix,
    input  logic [6:0]  hcount,
    input  logic [8:0]  vcount,
    // state shown on the drawing
    input  logic [23:0] dot_rgb,        // phosphor colour
    input  logic [15:0] key_down,       // hex keys held
    input  logic        fn_down,
    input  logic        rst_down,
    input  logic        led_on,         // tape running
    input  logic        cursor_show,
    input  logic [9:0]  cursor_x,
    input  logic [9:0]  cursor_y,
    output logic [7:0]  r,
    output logic [7:0]  g,
    output logic [7:0]  b,
    output logic        hs,
    output logic        vs,
    output logic        hblank,
    output logic        vblank
);

`include "desk_assets.svh"

localparam int HV = 800, HFP = 40, HSW = 128, HT = 1056;
localparam int VV = 600, VFP = 1,  VSW = 4,   VT = 628;

// ------------------------------------------------------------------ copy of the screen
logic sbuf [0:2047];
always_ff @(posedge clk)
    if (ce_dot && hcount < 7'd64 && vcount < 9'd128 && vcount[1:0] == 2'd1)
        sbuf[{vcount[6:2], hcount[5:0]}] <= pix;

// ------------------------------------------------------------------ background
logic [31:0] tiles [0:8191];
logic [9:0]  tmap  [0:7499];
initial begin
    $readmemh(TILES_FILE, tiles);
    $readmemh(MAP_FILE, tmap);
end

// stage 0: counters
logic [10:0] h0;
logic [9:0]  v0;
logic [12:0] rowbase;                    // (v0 / 8) * 100
always_ff @(posedge clk) begin
    if (h0 == 11'(HT - 1)) begin
        h0 <= 0;
        if (v0 == 10'(VT - 1)) begin v0 <= 0; rowbase <= 0; end
        else begin
            v0 <= v0 + 10'd1;
            if (v0[2:0] == 3'd7) rowbase <= rowbase + 13'd100;
        end
    end
    else h0 <= h0 + 11'd1;
end
wire        act0 = h0 < 11'(HV) && v0 < 10'(VV);
wire [12:0] maddr = act0 ? rowbase + 13'(h0[9:3]) : 13'd0;

// stage 1: map read; picture address
logic [10:0] h1, h2, h3;
logic [9:0]  v1, v2, v3;
logic [9:0]  mq;
logic        in1, in2;
logic [10:0] saddr1;
wire  [10:0] pdx = h0 - 11'(PIC_X);
wire  [9:0]  pdy = v0 - 10'(PIC_Y);
wire  [19:0] pcol = 20'(pdx) * 20'd205;   // /5, exact for 0..319
wire  [19:0] prow = 20'(pdy) * 20'd205;   // /5, exact for 0..159
always_ff @(posedge clk) begin
    mq <= tmap[maddr];
    h1 <= h0; v1 <= v0;
    in1 <= pdx < 11'(64 * PIC_DOT) && pdy < 10'(32 * PIC_DOT);
    saddr1 <= {prow[14:10], pcol[15:10]};
end

// stage 2: tile row, screen bit
logic [31:0] tq;
logic        sq;
always_ff @(posedge clk) begin
    tq <= tiles[{mq, v1[2:0]}];
    sq <= sbuf[saddr1];
    in2 <= in1;
    h2 <= h1; v2 <= v1;
end

// stage 3: colour index with the overlays
logic [3:0] bgi, ci;
logic [3:0] i3;
logic [4:0] k;
logic       kdown;
logic [1:0] apix;
wire  [10:0] cdx = h2 - 11'(cursor_x);
wire  [9:0]  cdy = v2 - cursor_y;
d6800_arrow arrow (.row(cdy[4:0]), .col(cdx[3:0]), .pix(apix));
always_comb begin
    bgi = tq[31 - 4 * h2[2:0] -: 4];
    k = key_at(h2[9:0], v2);
    kdown = k < 5'd16 ? key_down[k[3:0]] : k == 5'd16 ? rst_down : k == 5'd17 ? fn_down : 1'b0;
    ci = bgi;
    if (kdown) begin                         // pressed: key face in shadow, buttons darker
        if (bgi == C_KEY) ci = C_KEYSH;
        else if (bgi == C_RED) ci = C_BEZEL;
        else if (bgi == C_BLACK && k == 5'd17) ci = C_CAB2;
    end
    if (in2) ci = sq ? C_DOT : C_BLACK;
    if (cursor_show && cdx < 11'd12 && cdy < 10'd19 && apix != 2'b00)
        ci = apix == 2'b01 ? C_BLACK : C_KEY;
end
always_ff @(posedge clk) begin
    i3 <= ci;
    h3 <= h2; v3 <= v2;
end

// stage 4: palette, syncs
always_ff @(posedge clk) begin
    case (i3)
        C_DOT:   {r, g, b} <= dot_rgb;
        C_LED:   {r, g, b} <= led_on ? 24'hff3a24 : DESK_PAL[15];
        default: {r, g, b} <= DESK_PAL[i3];
    endcase
    hblank <= h3 >= 11'(HV);
    vblank <= v3 >= 10'(VV);
    hs <= h3 >= 11'(HV + HFP) && h3 < 11'(HV + HFP + HSW);
    vs <= v3 >= 10'(VV + VFP) && v3 < 10'(VV + VFP + VSW);
end

endmodule

// Mouse on the Desk view: pointer position, and the key under the pointer held while the
// left button is down (0-15 hex, 16 RST, 17 FN, 31 none).
module d6800_mouse (
    input  logic        clk,
    input  logic        reset,
    input  logic        enable,          // Desk view on
    input  logic [24:0] ps2_mouse,
    output logic [9:0]  mx,
    output logic [9:0]  my,
    output logic        mshow,
    output logic [15:0] mkey,
    output logic        mfn,
    output logic        mrst
);

`include "desk_assets.svh"

logic        old_m, left;
logic [4:0]  held;
logic [28:0] idle;                       // pointer hidden 10 s after the last movement
wire signed [11:0] dx = {{3{ps2_mouse[4]}}, ps2_mouse[4], ps2_mouse[15:8]};
wire signed [11:0] dy = {{3{ps2_mouse[5]}}, ps2_mouse[5], ps2_mouse[23:16]};
wire signed [11:0] nx = $signed({2'b00, mx}) + dx;
wire signed [11:0] ny = $signed({2'b00, my}) - dy;          // PS/2 Y grows upwards

assign mshow = enable && idle != 0;
assign mkey  = (enable && held < 5'd16) ? 16'd1 << held[3:0] : 16'd0;
assign mfn   = enable && held == 5'd17;
assign mrst  = enable && held == 5'd16;

always_ff @(posedge clk) begin
    old_m <= ps2_mouse[24];
    if (idle != 0) idle <= idle - 29'd1;
    if (reset) begin
        mx <= 10'd680; my <= 10'd380; left <= 0; held <= 5'd31; idle <= 0;
    end
    else if (old_m != ps2_mouse[24]) begin
        mx <= (nx < 0) ? 10'd0 : (nx > 12'sd799) ? 10'd799 : nx[9:0];
        my <= (ny < 0) ? 10'd0 : (ny > 12'sd599) ? 10'd599 : ny[9:0];
        if (dx != 0 || dy != 0) idle <= 29'd400_000_000;
        left <= ps2_mouse[0];
        if (ps2_mouse[0] && !left) held <= key_at(mx, my);
        if (!ps2_mouse[0]) held <= 5'd31;
    end
end

endmodule

// Arrow pointer, 12 x 19, hot spot at the top left corner (from the PLATO core).
// Returns 2'b00 transparent, 2'b01 black outline, 2'b10 white fill.
module d6800_arrow (
    input  logic [4:0] row,
    input  logic [3:0] col,
    output logic [1:0] pix
);
    logic [11:0] ol, fl;
    always_comb begin
        case (row)
            5'd0:  begin ol = 12'b100000000000; fl = 12'b000000000000; end
            5'd1:  begin ol = 12'b110000000000; fl = 12'b000000000000; end
            5'd2:  begin ol = 12'b101000000000; fl = 12'b010000000000; end
            5'd3:  begin ol = 12'b100100000000; fl = 12'b011000000000; end
            5'd4:  begin ol = 12'b100010000000; fl = 12'b011100000000; end
            5'd5:  begin ol = 12'b100001000000; fl = 12'b011110000000; end
            5'd6:  begin ol = 12'b100000100000; fl = 12'b011111000000; end
            5'd7:  begin ol = 12'b100000010000; fl = 12'b011111100000; end
            5'd8:  begin ol = 12'b100000001000; fl = 12'b011111110000; end
            5'd9:  begin ol = 12'b100000000100; fl = 12'b011111111000; end
            5'd10: begin ol = 12'b100000000010; fl = 12'b011111111100; end
            5'd11: begin ol = 12'b100000011111; fl = 12'b011111100000; end
            5'd12: begin ol = 12'b100010010000; fl = 12'b011101100000; end
            5'd13: begin ol = 12'b100110010000; fl = 12'b011001100000; end
            5'd14: begin ol = 12'b101001001000; fl = 12'b010000110000; end
            5'd15: begin ol = 12'b110001001000; fl = 12'b000000110000; end
            5'd16: begin ol = 12'b100000100100; fl = 12'b000000011000; end
            5'd17: begin ol = 12'b000000100100; fl = 12'b000000011000; end
            5'd18: begin ol = 12'b000000011000; fl = 12'b000000000000; end
            default: begin ol = 12'd0; fl = 12'd0; end
        endcase
        pix = (col > 4'd11) ? 2'b00 : ol[11 - col] ? 2'b01 : fl[11 - col] ? 2'b10 : 2'b00;
    end
endmodule
